import { Carousel, CarouselItem } from "@nativecn/ui/premium/layout/carousel";

export default function App() {
  const items = ["Slide One", "Slide Two", "Slide Three"];
  return (
    <Carousel>
      {items.map((item, i) => (
        <CarouselItem key={i}>
          <Text>{item}</Text>
        </CarouselItem>
      ))}
    </Carousel>
  );
}
